import { Component, Element, Event, EventEmitter, h, Host, Listen, Prop, Watch } from '@stencil/core';
import { AccordionIconPosition, AccordionSize } from '../../types';
import { KeyboardHelper } from '../../utils/keyboard-helper';

/**
 * @slot default - default slot for the content of the accordion
 * @slot headline - named slot 'headline', here is any HTML content allowed.
 */
@Component({
  tag: 'groupui-accordion',
  styleUrl: 'accordion.scss',
  shadow: { delegatesFocus: true },
})
export class Accordion {
  /**
   * indicates if the accordion is the first of multiple accordions
   */
  @Prop({ reflect: true }) readonly first: boolean;

  /**
   * sets the accordion size
   */
  @Prop({ reflect: true }) readonly size: AccordionSize = 'm';

  /**
   * sets the icon position. Possible options are 'right' (default), 'left', 'top-right', 'bottom-right', 'top-left', 'bottom-left'
   */
  @Prop({ reflect: true }) readonly iconPosition: AccordionIconPosition = 'right';

  /**
   * sets the indentation of the accordion
   */
  @Prop({ reflect: true }) readonly indentation: boolean;

  /**
   * removes the bottom line (separator)
   */
  @Prop({ reflect: true }) readonly noSeparator: boolean;

  /**
   * indicates if the accordion is expanded
   */
  @Prop({ reflect: true, mutable: true }) expanded: boolean = false;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  /**
   * dispatched when expanded state changes, 'expanded' is true when accordion expands, false when it collapses
   */
  @Event({ bubbles: false }) groupuiExpandedChanged: EventEmitter<{ expanded: boolean }>;

  @Element() host: HTMLElement;

  componentDidLoad() {
    this.groupuiDidLoad.emit();
  }

  private toggleExpand = () => {
    this.expanded = !this.expanded;
  };

  @Listen('keydown')
  onKeyUp(event: KeyboardEvent) {
    if (event.code === 'Space') {
      KeyboardHelper.preventDefaultSpace(event, this.host);
    }
    if (this.isHost(event) && (event.code === 'Enter' || event.code === 'Space')) {
      this.toggleExpand();
    }
  }

  @Watch('expanded')
  onExpandedChanged() {
    this.groupuiExpandedChanged.emit({ expanded: this.expanded });
  }

  private isHost(event: KeyboardEvent) {
    return (event.target as HTMLElement) === this.host;
  }

  private getIcon() {
    if (this.expanded) {
      return <groupui-icon id="arrow" name="chevron-up-24" aria-hidden="true" />;
    }
    return <groupui-icon id="arrow" name="chevron-down-24" aria-hidden="true" />;
  }

  render() {
    return (
      <Host>
        <div id="container">
          <div
            id="header"
            tabIndex={0}
            role="button"
            onClick={this.toggleExpand}
            aria-expanded={this.expanded ? 'true' : 'false'}
            aria-controls="content"
          >
            <slot name="headline" />
            {this.getIcon()}
          </div>
          {
            <section
              id="content"
              aria-hidden={this.expanded ? null : 'true'}
              aria-labelledby="header"
              style={!this.expanded && { display: 'none' }}
            >
              <slot />
            </section>
          }
        </div>
      </Host>
    );
  }
}
